package com.weeklyplan.partner;
import com.weeklyplan.company.Company; import com.weeklyplan.module.FeatureModuleService; import com.weeklyplan.project.Project; import com.weeklyplan.project.ProjectService; import com.weeklyplan.tenant.TenantAccessService; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class PartnerResourceService { private static final String MODULE="PARTNER_RESOURCE_MANAGEMENT"; private final PartnerResourceRepository resources; private final PartnerResourceContactRepository contacts; private final PartnerResourceFollowUpRepository followUps; private final PartnerResourceProjectRepository projects; private final ProjectService projectService; private final TenantAccessService tenant; private final FeatureModuleService modules; public PartnerResourceService(PartnerResourceRepository r,PartnerResourceContactRepository c,PartnerResourceFollowUpRepository f,PartnerResourceProjectRepository p,ProjectService ps,TenantAccessService t,FeatureModuleService m){resources=r;contacts=c;followUps=f;projects=p;projectService=ps;tenant=t;modules=m;} private void access(){modules.requireEnabled(MODULE);} @Transactional(readOnly=true) public List<PartnerResourceResponse> list(){access();return resources.findByCompanyIdOrderByPreferredDescUpdatedAtDesc(tenant.currentCompany().getId()).stream().map(PartnerResourceResponse::of).toList();} @Transactional public PartnerResourceResponse create(SavePartnerResourceRequest r){access();Company c=tenant.currentCompany();return PartnerResourceResponse.of(resources.save(PartnerResource.create(c,tenant.currentUser(),r)));} @Transactional public PartnerResourceResponse update(Long id,SavePartnerResourceRequest r){access();PartnerResource p=require(id);p.apply(r);return PartnerResourceResponse.of(p);} @Transactional public void delete(Long id){access();resources.delete(require(id));} @Transactional(readOnly=true) public List<PartnerResourceContactResponse> contacts(Long id){access();require(id);return contacts.findByResourceIdOrderByIdDesc(id).stream().map(PartnerResourceContactResponse::of).toList();} @Transactional public PartnerResourceContactResponse addContact(Long id,SavePartnerContactRequest r){access();return PartnerResourceContactResponse.of(contacts.save(PartnerResourceContact.create(require(id),r)));} @Transactional public void deleteContact(Long resourceId,Long id){access();require(resourceId);PartnerResourceContact c=contacts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"联系人不存在"));if(!c.getResource().getId().equals(resourceId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"联系人不存在");contacts.delete(c);} @Transactional(readOnly=true) public List<PartnerResourceFollowUpResponse> followUps(Long id){access();require(id);return followUps.findByResourceIdOrderByFollowUpDateDescCreatedAtDesc(id).stream().map(PartnerResourceFollowUpResponse::of).toList();} @Transactional public PartnerResourceFollowUpResponse addFollowUp(Long id,SavePartnerFollowUpRequest r){access();return PartnerResourceFollowUpResponse.of(followUps.save(PartnerResourceFollowUp.create(require(id),tenant.currentUser(),r)));} @Transactional public void deleteFollowUp(Long resourceId,Long id){access();require(resourceId);PartnerResourceFollowUp f=followUps.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"跟进记录不存在"));if(!f.getResource().getId().equals(resourceId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"跟进记录不存在");followUps.delete(f);} @Transactional(readOnly=true) public List<PartnerResourceProjectResponse> projects(Long id){access();require(id);return projects.findByResourceId(id).stream().map(PartnerResourceProjectResponse::of).toList();} @Transactional public PartnerResourceProjectResponse linkProject(Long id,SavePartnerProjectRequest r){access();PartnerResource resource=require(id);Project project=projectService.requireProject(r.projectId());if(projects.existsByResourceIdAndProjectId(id,r.projectId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"该项目已关联");return PartnerResourceProjectResponse.of(projects.save(PartnerResourceProject.create(resource,project,r)));} @Transactional public void unlinkProject(Long resourceId,Long projectId){access();require(resourceId);projectService.requireProject(projectId);projects.deleteByResourceIdAndProjectId(resourceId,projectId);} @Transactional(readOnly=true) public List<ProjectPartnerResourceResponse> listByProject(Long projectId){access();projectService.requireProject(projectId);return projects.findByProjectId(projectId).stream().map(ProjectPartnerResourceResponse::of).toList();} private PartnerResource require(Long id){PartnerResource p=resources.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"合作资源不存在"));tenant.assertCompany(p.getCompany());return p;} }
